    const expected: []const u8 = "💇";
    const actual = micro_blog.truncate("💇");
    try testing.expectEqualStrings(expected, actual);
}

test "Emoji long" {
    const expected: []const u8 = "❄🌡🤧🤒🏥";
    const actual = micro_blog.truncate("❄🌡🤧🤒🏥🕰😀");
    try testing.expectEqualStrings(expected, actual);
